pred_sql:
SELECT count(*) 
FROM orders 
WHERE order_status = 'delivered';

SELECT ROUND(AVG(payment_installments)::numeric, 2) AS avg_installments
FROM order_payments
WHERE payment_type = 'credit_card';

SELECT 
    ROUND(
        100.0 * SUM(CASE WHEN review_score IN (1, 2) THEN 1 ELSE 0 END) / COUNT(*), 
        2
    ) AS low_score_percentage
FROM order_reviews;

SELECT count(*) 
FROM products 
WHERE product_category_name IS NULL;

SELECT count(*) FROM (
    SELECT order_id
    FROM order_reviews
    GROUP BY order_id
    HAVING count(*) > 1
) t;

SELECT 
    ROUND(
        100.0 * COUNT(*) FILTER (WHERE order_status = 'canceled') / COUNT(*), 
        2
    ) AS cancellation_rate_percentage
FROM orders;
